{
  "findings": [
    {
      "check_id": "CKV_GCP_10",
      "title": "Cloud Run service exposed to all users (public access)",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "HIGH",
      "explanation": "The IAM binding grants the 'roles/run.invoker' role to 'allUsers', making the Cloud Run service publicly accessible without authentication. This exposes the application logic and potentially sensitive data or backend resources to anyone on the internet."
    }
  ],
  "patched_code": "# REMOVED: google_cloud_run_service_iam_binding.search_service_public\n# The resource granting public access ('allUsers') has been removed.\n# To secure this service, ensure that only specific authenticated members\n# are granted access via a separate IAM binding with appropriate principals,\n# or rely on default private access if no other bindings exist.",
  "fix_summary": "Removed the `google_cloud_run_service_iam_binding` resource that granted `roles/run.invoker` to `allUsers`, thereby eliminating the public exposure of the Cloud Run service. The file now contains no active resources, effectively securing the service by removing the misconfiguration."
}
